SELECT eixo_1.no_modalidade AS no_modalidade,   eixo_1.nome da sit matricula (situacao detalhada) AS nome da sit matricula (situacao detalhada),   SUM(CAST(eixo_1.number of records AS BIGINT)) AS sum:number of records:ok,   CAST(EXTRACT(YEAR FROM eixo_1.data_de_inicio) AS BIGINT) AS yr:data_de_inicio:ok FROM eixo_1 WHERE ((eixo_1.no_modalidade IN ('pronatec turismo cidadão', 'Pronatec turismo Desenvolvimento Local', 'PRONATEC TURISMO na EMPRESA', 'PRONATEC TURISMO SOCIAL')) AND (NOT ((eixo_1.nome da sit matricula (situacao detalhada) NOT IN ('', 'TRANSF_EXT', 'INTEGRALIZADA', 'FREQ_INIC_INSUF', 'TRANCADA', 'CONCLUÍDA', 'TRANSF_INT', 'EM_CURSO', 'REPROVADA', 'ABANDONO', 'CONFIRMADA', 'EM_DEPENDÊNCIA')) OR (eixo_1.nome da sit matricula (situacao detalhada) IS NULL))) AND ((CAST(EXTRACT(YEAR FROM eixo_1.data_de_inicio) AS BIGINT) IS NULL) OR ((CAST(EXTRACT(YEAR FROM eixo_1.data_de_inicio) AS BIGINT) >= 1201) AND (CAST(EXTRACT(YEAR FROM eixo_1.data_de_inicio) AS BIGINT) <= 3013))) AND (NOT (eixo_1.situacao_da_turma IN ('CANCELADA', 'CRIADA', 'PUBLICADA')))) GROUP BY eixo_1.no_modalidade,   eixo_1.nome da sit matricula (situacao detalhada), yr:data_de_inicio:ok;
